    dry_run: bool,
) -> None:
    out.mkdir(parents=True, exist_ok=True)
    safe = model.replace("/", "_")
    scenarios = SCENARIOS if api == "chat" else RESPONSES_SCENARIOS
    path = "/chat/completions" if api == "chat" else "/responses"
