            if api == "responses" and name in TWO_REQUEST:
                result = two_request(key, model, name, body | {"model": model})
                (out / f"{stem}.measure.json").write_text(json.dumps(result, indent=2) + "\n")
                print(f"{stem}.measure.json")
                continue
            try:
