    p.add_argument("--reasoning-effort")
    a = p.parse_args()
    valid = SCENARIOS if a.api == "chat" else RESPONSES_SCENARIOS
    bad = [s for s in a.only if s not in valid]
    if bad:
        print(f"unknown scenario for --api {a.api}: {', '.join(bad)}", file=sys.stderr)
