import json, sys, pathlib, re
SDK = pathlib.Path(sys.argv[2])
src = (SDK/"types/responses/response_stream_event.py").read_text()
mods = re.findall(r"from \.(\w+) import (\w+)", src)
known = set()
for mod, _ in mods:
    t = (SDK/"types/responses"/f"{mod}.py").read_text()
    m = re.findall(r'^    type: Literal\["([^"]+)"\]', t, re.M)
    known.update(m)
known.add("keepalive")
print("known types:", len(known), file=sys.stderr)
TERM = ("response.completed","response.incomplete","response.failed")
def recs(p):
    out=[]
    for blk in p.read_text().split("\n\n"):
        ev=None; data=None
        for line in blk.split("\n"):
            if line.startswith("event: "): ev=line[7:]
            if line.startswith("data: "): data=line[6:]
        if data is not None: out.append((ev, data))
    return out
for p in sorted(pathlib.Path(sys.argv[1]).glob("*.sse")):
    errs=[]
    rs=recs(p)
    evs=[json.loads(d) for e,d in rs if d!="[DONE]"]
    if evs[0]["type"]!="response.created": errs.append("R1 first")
    ids={e["response"]["id"] for e in evs if "response" in e}
    if len(ids)!=1: errs.append("R1 ids")
    for e in evs:
        if e["type"] in ("response.created","response.queued","response.in_progress") and e["response"].get("output")!=[]: errs.append("R2")
        if e["type"] not in known: errs.append("UNKNOWN "+e["type"])
    terms=[i for i,e in enumerate(evs) if e["type"] in TERM]
    if len(terms)!=1 or terms[0]!=len(evs)-1: errs.append(f"R3 {terms}")
    term=evs[terms[-1]]
    if not isinstance(term["response"].get("output"),list): errs.append("R3 output")
    added={}; done={}; nxt=0; item_ids=set(); call_ids=set()
    for e in evs:
        if e["type"]=="response.output_item.added":
            j=e["output_index"]
            if j!=nxt: errs.append("R4 order")
            nxt+=1
            it=e["item"]; added[j]=it
            if not it.get("id") or it["id"] in item_ids: errs.append("R8 id")
            item_ids.add(it.get("id"))
            if "call_id" in it:
                if it["call_id"] in call_ids: errs.append("R8 call_id")
                call_ids.add(it["call_id"])
            if str(it.get("id","")).startswith("msg_paigasus_"): errs.append("R8 prefix")
        elif e["type"]=="response.output_item.done":
            j=e["output_index"]
            if j in done: errs.append("R4 two done")
            done[j]=e["item"]
        elif "output_index" in e:
            j=e["output_index"]
            if j in done: errs.append("R16")
            if "item_id" in e and e["item_id"]!=added.get(j,{}).get("id"): errs.append(f"R6 item_id {e['type']}")
    out=term["response"]["output"]
    if len(out)!=len(added): errs.append(f"R10 len {len(out)} vs {len(added)}")
    for j,it in added.items():
        for k in ("type","id","call_id","namespace","name"):
            vals={json.dumps(x.get(k)) for x in (it, done.get(j,it), out[j] if j<len(out) else {})}
            if len(vals)>1: errs.append(f"R9 {j}.{k}")
        if j in done and j<len(out) and out[j]!=done[j]: errs.append(f"R10 eq {j}")
    print(p.name, "OK" if not errs else sorted(set(errs)))
EOF
