def sse(events: list[dict], done: bool = True) -> bytes:
    parts = [f"event: {e['type']}\ndata: {json.dumps(e)}\n\n" for e in events]
    if done:
        parts.append("data: [DONE]\n\n")
    return "".join(parts).encode()

